'use strict';
const BRAND_UI5={bind,brandDialog,coffeeView,liveView,help};
TITLES.branding='Studio značek & marketing';
let brandingBrand5=state.brands[0].id,brandingBlend5=state.blends[0].id;
const markNames5={monogram:'Monogram',bean:'Kávové zrno',cup:'Šálek',seal:'Pečeť'},labelNames5={cream:'Krémová',kraft:'Kraftová',dark:'Tmavá'};
function brandMarkSvg5(p){const symbol=p.mark==='bean'?'<ellipse cx="40" cy="40" rx="18" ry="25" transform="rotate(35 40 40)"/><path d="M50 18Q27 34 31 60" fill="none" stroke="var(--brand)" stroke-width="3"/>':p.mark==='cup'?'<path d="M18 29H56V48Q56 63 37 63Q18 63 18 48Z"/><path d="M56 32H62Q75 32 69 45Q66 50 56 49M22 68H62M29 12V21M42 10V21" fill="none" stroke="currentColor" stroke-width="3"/>':p.mark==='seal'?`<circle cx="40" cy="40" r="30" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="40" cy="40" r="25" fill="none" stroke="currentColor"/><text x="40" y="48" text-anchor="middle" font-size="22" fill="currentColor">${esc(p.monogram)}</text>`:`<text x="40" y="51" text-anchor="middle" font-size="32" font-family="Georgia,serif" fill="currentColor">${esc(p.monogram)}</text>`;return `<svg viewBox="0 0 80 80" role="img" aria-label="${esc(markNames5[p.mark])}" style="color:${esc(p.accent)};fill:${esc(p.accent)}">${symbol}</svg>`;}
function brandSign5(data){return `<div class="brand-sign5" style="--brand:${esc(data.color)};--accent:${esc(data.accent)}">${brandMarkSvg5(data)}<div><strong>${esc(data.name)}</strong><span>${esc(data.tagline||'Tvoje místo pro kávu')}</span></div></div>`;}
function coffeeBag5(b,data){const owner=brand(data.brand),p=owner.identity5;return `<div class="brand-bag5 ${esc(data.style)}" style="--brand:${esc(owner.color)};--accent:${esc(p.accent)}"><div class="bag-label5">${brandMarkSvg5(p)}<small>${esc(owner.name)}</small><strong>${esc(data.name)}</strong><span>${esc(recipe(b).taste)}</span><i>${esc(data.story||'Od zrna k tvému šálku.')}</i><small>${b.share} % ${esc(ORIGINS[b.primary].name.split(' · ')[0])} · ${100-b.share} % ${esc(ORIGINS[b.secondary].name.split(' · ')[0])}</small></div></div>`;}
function readBrandIdentity5(){return {name:el('identityName5').value.trim(),concept:el('identityConcept5').value,color:el('identityColor5').value,budget:Number(el('identityBudget5').value),position:el('identityPosition5').value,mark:el('identityMark5').value,monogram:el('identityMono5').value.trim().toUpperCase(),accent:el('identityAccent5').value,tagline:el('identityTagline5').value.trim(),story:el('identityStory5').value.trim()};}
function readCoffeeLabel5(){return {brand:el('labelBrand5').value,name:el('labelName5').value.trim(),style:el('labelStyle5').value,story:el('labelStory5').value.trim(),packaging:el('labelPackaging5').value};}
function readBrandCampaign5(){return {brand:brandingBrand5,target:el('campaignTarget5').value,channel:el('campaignChannel5').value,city:el('campaignCity5').value,weekly:Number(el('campaignWeekly5').value),weeks:Number(el('campaignWeeks5').value)};}
function brandingView(){if(!brand(brandingBrand5))brandingBrand5=state.brands[0].id;if(!blend(brandingBlend5))brandingBlend5=state.blends[0].id;const b=brand(brandingBrand5),p=b.identity5,d=brandingIdentityData5(b),coffee=blend(brandingBlend5),label=coffee.label5,last=state.branding5.last?.brands.find(x=>x.id===b.id),campaigns=state.branding5.campaigns.filter(c=>c.brand===b.id);return `<div class="view-toolbar"><p class="intro">Dej kavárnám a vlastní kávě společnou tvář. Jasný slib přitáhne cílové hosty; jejich zkušenost rozhodne, zda se budou vracet.</p><button class="soft" id="brandingNew5" ${state.brands.length>=8||state.over?'disabled':''}>Nová značka +</button></div><div class="fields">${field('Značka',`<select id="brandingBrand5">${brandOptions(b.id)}</select>`)}</div><div class="report-overview5">${metric('POBOČKY',state.stores.filter(s=>s.brand===b.id).length,CONCEPTS[b.concept].name)}${metric('PŘÍSPĚVEK ZNAČKY',last?money(last.profit):'—',last?'T'+last.week+' · po vlastním marketingu':'Odehraj týden')}${metric('SPOKOJENOST HOSTŮ',last?.satisfaction!=null?number(last.satisfaction,1)+' / 100':'—','Zkušenost skutečných příchozích')}${metric('ZNAČKU ZNAJÍ',number(Math.max(...Object.values(p.awareness)),1)+' / 100','Nejsilnější cílová skupina')}</div><div class="actions"><button class="soft" data-brand-report5="brands">Report značek</button><button class="soft" data-brand-report5="products">Report balené kávy</button><button class="quiet" data-goto="guests">Zkušenosti hostů</button></div><div class="branding-grid5"><section class="card"><span class="eyelabel">IDENTITA KAVÁREN</span><h2>Jméno, vzhled a slib</h2><div class="fields">${field('Název',`<input id="identityName5" maxlength="40" value="${esc(d.name)}">`)}${field('Symbol',`<select id="identityMark5">${BRAND_MARKS5.map(k=>option(k,markNames5[k],d.mark)).join('')}</select>`)}${field('Monogram · 1 až 3 znaky',`<input id="identityMono5" maxlength="3" value="${esc(d.monogram)}">`)}${field('Hlavní barva',`<input id="identityColor5" type="color" value="${esc(d.color)}">`)}${field('Akcent',`<input id="identityAccent5" type="color" value="${esc(d.accent)}">`)}${field('Koncept provozu',`<select id="identityConcept5">${Object.entries(CONCEPTS).map(([k,c])=>option(k,c.name,d.concept)).join('')}</select>`)}${field('Co značka slibuje',`<select id="identityPosition5">${Object.entries(POSITIONS5).map(([k,c])=>option(k,c.name,d.position)).join('')}</select>`)}${field('Běžný marketing / týden',input('identityBudget5',d.budget,0,20000,500))}</div>${field('Slogan · nejvýše 70 znaků',`<input id="identityTagline5" maxlength="70" value="${esc(d.tagline)}">`)}${field('Příběh značky · nejvýše 300 znaků',`<textarea id="identityStory5" rows="3" maxlength="300">${esc(d.story)}</textarea>`)}<div id="identityQuote5" class="sub"></div><button class="primary" id="identitySave5" ${state.over?'disabled':''}>Prověřit změnu identity</button></section><section class="card brand-preview5"><span class="eyelabel">NÁHLED OZNAČENÍ KAVÁRNY</span><div id="identityPreview5">${brandSign5(d)}</div><h3>Jak splnit slib</h3><p id="identityPromise5"></p><p class="sub">Náhled nic neplatí. Změna návrhu stojí 2 500 Kč, výměna označení 1 500 Kč za vlastní pobočku. Změna konceptu přidá polovinu jeho zakládací ceny. Franšízy si vzhled upraví na vlastní náklady. Stejný uložený návrh je zdarma.</p><h3>Znalost mezi hosty</h3>${GUEST_KEYS5.map(k=>`<div class="brand-awareness5"><span>${GUEST_TYPES5[k].name}</span><div class="bar"><i style="width:${p.awareness[k]}%"></i></div><strong>${number(p.awareness[k],1)}</strong></div>`).join('')}<p class="sub">Roste po skutečně zaplacené kampani podle obsluhy a spokojenosti cílových hostů. Každý týden se sníží o 2 % své hodnoty.</p></section></div><div class="branding-grid5"><section class="card"><span class="eyelabel">VLASTNÍ BALENÁ KÁVA</span><h2>Etiketa & obal</h2><div class="fields">${field('Receptura',`<select id="brandingBlend5">${blendOptions(coffee.id)}</select>`)}${field('Značka na etiketě',`<select id="labelBrand5">${brandOptions(label.brand)}</select>`)}${field('Jméno produktu',`<input id="labelName5" maxlength="40" value="${esc(label.name)}">`)}${field('Vzhled etikety',`<select id="labelStyle5">${LABEL_STYLES5.map(k=>option(k,labelNames5[k],label.style)).join('')}</select>`)}${field('Obal',`<select id="labelPackaging5">${option('classic','Klasický · 20 Kč/kg',coffee.packaging)}${option('premium','Prémiový · 45 Kč/kg',coffee.packaging)}${option('eco','Recyklovatelný · 32 Kč/kg',coffee.packaging)}</select>`)}</div>${field('Příběh kávy · nejvýše 250 znaků',`<textarea id="labelStory5" rows="3" maxlength="250">${esc(label.story)}</textarea>`)}<div id="labelQuote5" class="sub"></div><button class="primary" id="labelSave5" ${state.over?'disabled':''}>Prověřit etiketu</button><p class="sub">Návrh stojí 1 500 Kč. Tisk přidá 4 Kč/kg kávy skutečně zabalené e-shopem a novými B2B smlouvami; káva do kaváren se tím nezdraží. Vzhled nezmění staré šarže ani jejich kvalitu.</p></section><section class="card brand-preview5"><span class="eyelabel">NÁHLED PRODUKTU</span><div id="labelPreview5">${coffeeBag5(coffee,{...label})}</div><p class="sub">Název produktu je nezávislý na názvu receptury. Etiketa patří vybrané značce; její znalost a splnění slibu kvality ovlivní zájem e-shopu. E-shop potřebuje hotový IT projekt, pracovníka IT a dostupnou kávu.</p><button class="soft" data-goto="coffee">Receptury a zásoby</button></section></div><section class="card"><span class="eyelabel">CÍLENÝ MARKETING</span><h2>Oslov správné hosty</h2><div class="fields">${field('Cílová skupina',`<select id="campaignTarget5">${GUEST_KEYS5.map(k=>option(k,GUEST_TYPES5[k].name,'community')).join('')}</select>`)}${field('Kanál',`<select id="campaignChannel5">${Object.entries(CAMPAIGN_CHANNELS5).map(([k,c])=>option(k,c.name,'local')).join('')}</select>`)}${field('Město',`<select id="campaignCity5">${cityOptions('all',true)}</select>`)}${field('Rozpočet / týden',input('campaignWeekly5',3000,1500,20000,500))}${field('Doba kampaně',`<select id="campaignWeeks5">${option(4,'4 placené týdny',4)}${option(8,'8 placených týdnů',4)}</select>`)}</div><p id="campaignQuote5" class="sub"></p><div class="actions"><button class="soft" data-campaign-preview5="4">Porovnat 4 týdny</button><button class="soft" data-campaign-preview5="8">Porovnat 8 týdnů</button><button class="primary" id="campaignStart5" ${state.over?'disabled':''}>Prověřit spuštění</button></div><p class="sub">Nejvýše čtyři aktivní či pozastavené kampaně. Každý tah se platí jen při zachování rezervy dvou týdnů fixních nákladů a existenci cílové kavárny. Nezaplacený týden nepřidá návštěvnost a nespotřebuje dobu kampaně; čekající kampaň se může automaticky obnovit. Pozastavení nebo zrušení zastaví další útratu.</p><div class="cards">${campaigns.slice().reverse().map(c=>`<article class="card"><div class="card-head"><h3>${GUEST_TYPES5[c.target].name}</h3><span class="badge">${({active:'Aktivní',paused:'Pozastavená',done:'Dokončená',cancelled:'Zrušená'})[c.status]}</span></div><p class="sub">${CAMPAIGN_CHANNELS5[c.channel].name} · ${esc(c.city==='all'?'Všechna města':c.city)} · ${money(c.weekly)} / týden</p>${rows([['Zbývá placených týdnů',c.remaining+' / '+c.weeks],['Zaplaceno týdně',money(c.spent)],['Návštěvy / obslouženo minule',c.last?c.last.arrivals+' / '+c.last.served:'—'],['Spokojenost minule',c.last?.satisfaction!=null?number(c.last.satisfaction,1)+' / 100':'—']])}<p class="sub">${esc(c.last?.reason||'Příprava 1 200 Kč; čeká na další tah.')}</p>${['active','paused'].includes(c.status)?`<div class="actions"><button class="soft" data-campaign-status5="${c.id}" data-status="${c.status==='active'?'paused':'active'}" ${state.over?'disabled':''}>${c.status==='active'?'Pozastavit':'Obnovit'}</button><button class="quiet" data-campaign-status5="${c.id}" data-status="cancelled" ${state.over?'disabled':''}>Zrušit</button></div>`:''}</article>`).join('')||empty('Zatím žádná kampaň této značky. Nejprve ulož identitu a otevři její kavárnu.')}</div></section><section class="card" style="margin-top:24px"><h2>Výsledky značky${last?' · T'+last.week:''}</h2>${last?rows([['Tržby firmy z poboček a e-shopu',money(last.revenue)],['Příspěvek po marketingu',money(last.profit)],['Návštěvy stálých hostů',last.returned+' / '+last.served+' obsloužených'],['Cílené kampaně',money(last.campaignCost)],['Běžný marketing a změny identity',money(last.sharedCost)]]):empty('Výsledky se objeví po odehrání týdne.')}<p class="sub">Příspěvek zahrnuje provoz poboček a e-shop po kávě, obalu, expedici a marketingu této značky. Franšízy započítají příjem tvé firmy. Centrála, fixní náklady výroby a B2B obchod jsou ve výsledku celé firmy. Návštěvy cílové skupiny během kampaně nejsou měřením její samostatné zásluhy.</p></section>`;}
function updateBrandingPreview5(){try{const data=readBrandIdentity5(),q=brandIdentityQuote5(brandingBrand5,data),pos=POSITIONS5[data.position];el('identityPreview5').innerHTML=brandSign5(data);el('identityQuote5').textContent='Návrh '+money(q.design)+' · označení '+q.stores.length+' poboček '+money(q.signs)+' · koncept '+money(q.concept)+' · celkem '+money(q.cost)+'.';el('identityPromise5').textContent=data.position==='original'?'Zachová současné cenové očekávání a nepřidá nový slib.':(pos.targets.map(k=>GUEST_TYPES5[k].name).join(', ')+': očekávání ceny '+number(pos.price*100)+' % místního základu, skutečná kvalita kávy alespoň '+pos.quality+'/100'+(pos.wait?', čekání nejvýše '+pos.wait+' minut':'')+'. Nesplnění snižuje spokojenost; ceny se mění pouze v menu.');}catch(e){el('identityQuote5').textContent=e.message;}}
function updateLabelPreview5(){try{const data=readCoffeeLabel5(),q=coffeeLabelQuote5(brandingBlend5,data);el('labelPreview5').innerHTML=coffeeBag5(blend(brandingBlend5),data);el('labelQuote5').textContent='Návrh '+money(q.cost)+' · obal včetně vlastního tisku '+money(q.pack)+'/kg skutečně balené kávy.';}catch(e){el('labelQuote5').textContent=e.message;}}
function updateCampaignQuote5(){try{const q=brandingCampaignQuote5(readBrandCampaign5());el('campaignQuote5').textContent='Příprava '+money(q.fee)+' · plán při úplném doběhnutí '+money(q.total)+' · '+q.stores.length+' cílových poboček · dodatečný modelový zájem skupiny '+number(q.boost*100,1)+' %. '+(q.eligible?'Rezerva před platbou musí pokrýt '+money(weeklyFixed()*2)+' fixních nákladů.':'Nejprve aktivuj identitu a otevři její kavárnu ve vybraném městě; zároveň musí být volné místo mezi čtyřmi kampaněmi.');}catch(e){el('campaignQuote5').textContent=e.message;}}
function brandCampaignPreviewDialog5(data,weeks){const p=previewBrandCampaign5(data,weeks),a=p.baseline.series,b=p.campaign.series,sum=(series,k)=>series.reduce((n,h)=>n+h[k],0),end=series=>series.at(-1)?.cash??state.cash;show(`<span class="eyelabel">SROVNÁVACÍ VÝHLED · ${weeks} TÝDNŮ</span><h2>Firma s kampaní a bez ní</h2><p>Kopie celé firmy používá stejné zásoby, fronty, mzdy, soupeře a události. Současná hra zůstává v týdnu ${state.week}. Varianta bez nové kampaně ponechá všechny již běžící kampaně.</p><div class="table-scroll"><table class="data"><thead><tr><th>Výsledek</th><th>Bez nové kampaně</th><th>S novou kampaní</th><th>Rozdíl</th></tr></thead><tbody>${[['Výsledek celé firmy',sum(a,'profit'),sum(b,'profit'),'money'],['Hotovost na konci',end(a),end(b),'money'],['Obsloužené návštěvy značky',sum(a,'served'),sum(b,'served'),'count'],['Příchozí návštěvy značky',sum(a,'arrivals'),sum(b,'arrivals'),'count'],['Týdenní výdaje kampaní značky',sum(a,'spend'),sum(b,'spend'),'money']].map(([title,x,y,kind])=>`<tr><td>${title}</td><td>${kind==='money'?money(x):number(x)}</td><td>${kind==='money'?money(y):number(y)}</td><td>${kind==='money'?money(y-x):number(y-x)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Zisk a hotovost zahrnují přípravu kampaně. Jde o herní odhad při současných pravidlech; ruční zásahy a změny podmínek mohou výsledek změnit. ${p.baseline.over||p.campaign.over?'Jedna varianta skončila před koncem období.':'Obě varianty dokončily období.'}</p><button class="soft" id="campaignPreviewClose5">Zavřít porovnání</button>`);el('campaignPreviewClose5').onclick=()=>el('modal').close();}
brandDialog=function(id){if(id){brandingBrand5=id;goto('branding');}else BRAND_UI5.brandDialog();};
coffeeView=function(){return `<div class="actions"><button class="primary" data-goto="branding">Navrhnout značky a etikety</button></div>`+BRAND_UI5.coffeeView();};
liveView=function(){const s=state.stores.find(s=>s.id===liveStore)||state.stores[0],b=s?brand(s.brand):null;return (b?.identity5.enabled?'<span class="eyelabel">AKTUÁLNÍ OZNAČENÍ KAVÁRNY</span>'+brandSign5(brandingIdentityData5(b)):'')+BRAND_UI5.liveView();};
bind=function(){BRAND_UI5.bind();if(el('brandingBrand5')){el('brandingBrand5').onchange=()=>{brandingBrand5=el('brandingBrand5').value;render();};el('brandingBlend5').onchange=()=>{brandingBlend5=el('brandingBlend5').value;render();};el('brandingNew5').onclick=()=>brandDialog();for(const id of ['identityName5','identityConcept5','identityColor5','identityBudget5','identityPosition5','identityMark5','identityMono5','identityAccent5','identityTagline5','identityStory5'])el(id).oninput=el(id).onchange=updateBrandingPreview5;for(const id of ['labelBrand5','labelName5','labelStyle5','labelStory5','labelPackaging5'])el(id).oninput=el(id).onchange=updateLabelPreview5;for(const id of ['campaignTarget5','campaignChannel5','campaignCity5','campaignWeekly5','campaignWeeks5'])el(id).onchange=updateCampaignQuote5;
 el('identitySave5').onclick=()=>{try{const id=brandingBrand5,data=readBrandIdentity5(),q=brandIdentityQuote5(id,data);confirmAction('Uložit identitu značky?',`Návrh ${money(q.design)}, označení ${q.stores.length} vlastních poboček ${money(q.signs)}, koncept ${money(q.concept)}. Celkem ${money(q.cost)}. Běžný marketing ${money(data.budget)}/týden. Slib ovlivní očekávání hostů od příštího týdne.`,()=>commitBrandIdentity5(id,data,q),'Uložit a zaplatit');}catch(e){toast(e.message);}};
 el('labelSave5').onclick=()=>{try{const id=brandingBlend5,data=readCoffeeLabel5(),q=coffeeLabelQuote5(id,data);confirmAction('Použít vlastní etiketu?',`Návrh ${money(q.cost)}. Obal a tisk ${money(q.pack)}/kg skutečně balené kávy. Staré skladové náklady se nemění.`,()=>commitCoffeeLabel5(id,data,q),'Použít etiketu');}catch(e){toast(e.message);}};
 el('campaignStart5').onclick=()=>{try{const data=readBrandCampaign5(),q=brandingCampaignQuote5(data);if(!q.eligible)throw Error('Nejprve aktivuj identitu, otevři cílovou kavárnu a uvolni místo mezi čtyřmi kampaněmi.');confirmAction('Spustit cílenou kampaň?',`Teď příprava ${money(q.fee)}. Potom ${money(data.weekly)} za každý z ${data.weeks} placených týdnů; celkový plán ${money(q.total)}. Platby se přeruší, pokud by narušily rezervu.`,()=>startBrandCampaign5(data,q),'Spustit');}catch(e){toast(e.message);}};
 on('[data-campaign-preview5]',b=>{try{brandCampaignPreviewDialog5(readBrandCampaign5(),Number(b.dataset.campaignPreview5));}catch(e){toast(e.message);}});on('[data-campaign-status5]',b=>{if(b.dataset.status==='cancelled')confirmAction('Ukončit kampaň?','Příprava ani již zaplacené týdny se nevracejí. Žádné další týdenní platby.',()=>setBrandCampaignStatus5(b.dataset.campaignStatus5,b.dataset.status),'Ukončit');else act(()=>setBrandCampaignStatus5(b.dataset.campaignStatus5,b.dataset.status),'Stav kampaně uložen.');});on('[data-brand-report5]',b=>{reportKind5=b.dataset.brandReport5;goto('performance');});updateBrandingPreview5();updateLabelPreview5();updateCampaignQuote5();}
 // Replace the original select listener so a rebrand cannot happen before its confirmation.
 document.querySelectorAll('[data-store-field="brand"]').forEach(old=>{const select=old.cloneNode(true);old.replaceWith(select);select.onchange=()=>{const id=select.dataset.store,to=select.value;try{const q=brandingRebrandQuote5(id,to);select.value=q.from;confirmAction('Změnit značku kavárny?',`${esc(loc(id).name)} → ${esc(brand(to).name)}. Označení a koordinace ${money(q.fee)}. Místní okruh stálých hostů zůstává.`,()=>rebrandStore5(id,to,q),'Změnit značku');}catch(e){toast(e.message);render();}};});};
help=function(){BRAND_UI5.help();const p=document.createElement('p');p.textContent='Studio značek: vlastní symbol, barvy, slogan, příběh a obchodní slib. Prémiová kvalita či rychlá obsluha musí odpovídat skutečné kávě a čekání. Etikety patří samostatným značkám; vlastní tisk se účtuje jen skutečně baleným prodejům. Kampaně mají konec, cílové hosty a města, ruční pozastavení a ochranu rezervy. Srovnávací výhled ukáže dvě kopie firmy. Report má kategorie Značky a Balená káva.';el('modalContent').append(p);};el('help').onclick=help;
render();
